package ro.leo.visual;
import android.content.*;import android.os.Bundle;import android.provider.Settings;import java.util.*;import java.io.*;import java.util.concurrent.TimeUnit;
public final class DisplaySettingsActivity extends LeoActivity {
    protected void onResume(){super.onResume();show();}
    static int keylightLevel(){try{Class<?> properties=Class.forName("android.os.SystemProperties");String value=(String)properties.getMethod("get",String.class,String.class).invoke(null,"persist.leo.keylight.level","20");return Integer.parseInt(value);}catch(Exception e){return 20;}}
    private void show(){int brightness=Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,128),timeout=Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,60000);list("Ecran și taste",Arrays.asList("Luminozitate · "+Math.round(brightness*100f/255)+"%","Stingere ecran · "+timeout/1000+" secunde","Iluminare taste · "+keylightLevel(),"Fundaluri și teme","Blocare automată taste","Dimensiunea textului Leo"),0,new Choice(){public void pick(int i){if(i==0)options("Luminozitate",new String[]{"5%","25%","50%","75%","100%"},new Choice(){public void pick(int at){setBrightness(new int[]{13,64,128,192,255}[at]);show();}});else if(i==1)options("Stingere ecran",new String[]{"30 secunde","1 minut","2 minute","5 minute","10 minute","30 minute"},new Choice(){public void pick(int at){setTimeout(new int[]{30000,60000,120000,300000,600000,1800000}[at]);show();}});else if(i==2)keylight();else if(i==3)startActivity(new Intent(DisplaySettingsActivity.this,WallpaperActivity.class));else if(i==4)startActivity(new Intent(DisplaySettingsActivity.this,KeypadLockSettingsActivity.class));else startActivity(new Intent(DisplaySettingsActivity.this,InputSettingsActivity.class));}},"",null);}
    void setBrightness(int value){if(value<13||value>255)return;try{Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL);Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,value);}catch(RuntimeException e){notice("Luminozitate nesalvată");}}
    void setTimeout(int value){if(value<30000||value>1800000)return;try{Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,value);}catch(RuntimeException e){notice("Interval nesalvat");}}
    private void keylight(){if(!new File("/sys/class/leds/button-backlight").isDirectory()||!new File("/system/bin/leo-su").canExecute()){notice("Controlul iluminării nu este disponibil");return;}options("Iluminare la apăsare · 8 secunde",new String[]{"Oprită","Slabă","Normală","Puternică"},new Choice(){public void pick(int at){final int value=new int[]{0,8,20,40}[at];worker.execute(new Runnable(){public void run(){final boolean ok=setKeylight(value);ui(new Runnable(){public void run(){notice(ok?"Se aplică la următoarea apăsare a unei taste":"Iluminarea nu poate fi schimbată");show();}});}});}});}
    static boolean setKeylight(int value){if(value!=0&&value!=8&&value!=20&&value!=40)return false;Process p=null;try{p=new ProcessBuilder("/system/bin/leo-su","-c","setprop persist.leo.keylight.level "+value).redirectErrorStream(true).start();if(!p.waitFor(3,TimeUnit.SECONDS)){p.destroy();return false;}return p.exitValue()==0&&keylightLevel()==value;}catch(Exception e){return false;}finally{if(p!=null){try{p.getInputStream().close();p.getOutputStream().close();}catch(IOException ignored){}}}}
}
